"""Add attachment metadata and write the reviewable catalog without altering meshes."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parent;OUT=ROOT.parents[2]/'docs/artifacts/city-run/v3'
p=ROOT/'manifest.json';m=json.loads(p.read_text())
for a in m['assets']:
 w,h,d=a['dimensionsRobloxXYZ']
 a['snapGridStuds']=1
 a['attachmentsRobloxLocal']={'base':[0,0,0],'top':[0,h,0],'front':[0,h/2,d/2],'back':[0,h/2,-d/2]}
 a['renderRecommendation']={'anchored':True,'canCollide':False,'canTouch':False,'canQuery':False,'doubleSided':False,'collisionFidelity':'Box','castShadow':a['family'] in ['Architecture','Roofs','Landmarks']}
 a['reusesSharedMaterial']='V3_Shared_Painted_Atlas'
 if a['family']=='Vehicles':
  a['forwardAxisRoblox']=[0,0,1];a['yawDegreesForPositiveXTraffic']=90
  a['runtimeNote']='Attach as visual only after comparing native actor pivot. Do not derive or replace runtime collider from this mesh.'
 if a['id'].startswith('V3_Awning_'):
  a['attachmentsRobloxLocal']['wallMount']=[0,1.4,-3.7];a['attachmentsRobloxLocal']['walkingSkinTop']=[0,2.775,0]
 if a['id']=='V3_WreckingBallSkin':a['attachmentsRobloxLocal']['cable']=[0,11.8,0];a['attachmentsRobloxLocal']['ballCenter']=[0,5,0]
 if a['id']=='V3_ClockTower':a['recommendedRoof']='V3_GableRoof_Narrow scaled (0.8,1,0.8) in Roblox local XYZ; bottom at tower top'
m['assemblyCoverage']={'crane':'Reuse V3_CraneTruss + V3_ScaffoldBay; retain existing moving cable/winch/pivot assembly. New shells never replace collision or swing geometry.','viaduct':'Repeat V3_ArchPortal + V3_RailBed; close visible ends with V3_FacadeStrip/solid native abutment. Test all joins in Pass2.','terminal':'V3_Terminal_Wing + V3_ClockTower + V3_GableRoof_Narrow/Wide + V3_TerminalColonnade + V3_BarrelRoof + V3_Sign_Terminal.','course':'All existing gameplay transforms, tags, settings and trigger dimensions must be preserved from live source before Pass2.'}
m['package']={'file':'CityRun_V3_AssetKit.fbx','sha256':hashlib.sha256((ROOT/'CityRun_V3_AssetKit.fbx').read_bytes()).hexdigest(),'bytes':(ROOT/'CityRun_V3_AssetKit.fbx').stat().st_size,'importStrategy':'Import shared package once; clone canonical imported meshes. Verify shared image ContentId, scale, pivots and opaque flags in Roblox before assembly.'}
p.write_text(json.dumps(m,indent=2))
lines=['# City Run V3 painted asset kit','',f"Build: **{m['build']}**. Pass 1 only; V1/V2 and gameplay remain unchanged.",'','## Contents','',f"- {m['totals']['uniqueAssets']} unique reusable meshes; {m['totals']['triangles']:,} triangles across one copy of the library.",f"- Largest asset: {m['totals']['maxAssetTriangles']:,} triangles.",'- One opaque 2048 x 1024 painted atlas and one shared material.','- Editable .blend, single-package FBX, per-asset FBXs, deterministic generators, manifest and mounting metadata.','- Atlas RGBA8 + full mip-chain estimate: 10.67 MiB; actual Roblox memory unmeasured. roblox_import.json confirms one shared image ID for all 64 kit05 meshes.','','## Rebuild','',r'Run from the project root using Blender 5.2 and Python with Pillow:','','```powershell','python assets/city_run/v3/paint_atlas.py',r"& 'C:\Program Files\Blender Foundation\Blender 5.2\blender.exe' --background --python assets/city_run/v3/build_asset_kit.py",r"& 'C:\Program Files\Blender Foundation\Blender 5.2\blender.exe' --background --python assets/city_run/v3/render_gallery.py",r"& 'C:\Program Files\Blender Foundation\Blender 5.2\blender.exe' --background --python assets/city_run/v3/audit_assets.py",'python assets/city_run/v3/write_catalog.py','```','','The refine_*.py files are historical one-time authoring patches, not rebuild steps.','','## Editing and import','', '- Each mesh lives in its own named Blender collection; use Edit Mode and linked-piece selection for fine adjustments.','- Source uses Z-up; FBX exports Y-up. Kit05 cloud import was enlarged about 24.236689 times; import_review05.luau restores manifest dimensions and source editing pivots. All 64 meshes passed the native check.','- Origins are bottom-center; mounting sockets and recommended flags are in manifest.json.','- Import the combined package once and clone canonical meshes. Importing every FBX separately could duplicate texture IDs.','- Texture is packed into .blend and embedded in FBX; the editable generator and external PNG are included.','- Renders include temporary gallery floors, scale markers and fit fixtures; those are excluded from exports.','- Fit images are assembly studies, not the actual map or proof of race clearance.','- Reuse runtime-owned cable/winch assemblies, colliders and hazard controllers; vehicle skins require explicit axis/pivot checks.','','## Catalog','','| Asset | Family | Tier | Roblox size X/Y/Z | Triangles |','|---|---|---|---|---:|']
for a in m['assets']:lines.append('| '+a['id']+' | '+a['family']+' | '+a['tier']+' | '+ ' / '.join(f'{v:.2f}'for v in a['dimensionsRobloxXYZ'])+' | '+str(a['triangles'])+' |')
lines+=['','## Validation boundary','','Local kit05 geometry and FBX round-trip checks pass. Approved kit05 upload and native verification are recorded in roblox_import.json and docs/artifacts/city-run/v3/studio07/import-audit.json: 64 meshes, one shared texture, zero dimension/pivot/flag errors. Course assembly, mobile benchmarks and 20-player validation remain outstanding.']
(ROOT/'BASE_CATALOG.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(m['totals']))
